const $=id=>document.getElementById(id);let token='';const notice=s=>$('notice').textContent=s;
async function api(method='GET',data){const r=await fetch('/api/admin/my-activity',{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function load(){const t=token,d=await api();if(!token||t!==token)return;$('mission').replaceChildren(new Option('Sélectionner',''));for(const m of d.missions.filter(m=>m.status==='ACTIVE'))$('mission').append(new Option(m.title+' ('+m.mode+')',m.id));$('rows').replaceChildren();for(const a of d.items){const r=document.createElement('tr');for(const v of [d.missions.find(m=>m.id===a.mission_id)?.title||'Mission',a.work_date,a.worked,a.status]){const c=document.createElement('td');c.textContent=v;r.append(c)}$('rows').append(r)}}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();$('login').hidden=true;$('workspace').hidden=false}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{token='';$('cra').reset();$('mission').replaceChildren();$('rows').replaceChildren();$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};
$('cra').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await load();notice('CRA soumis.')}catch(e){notice(e.message)}finally{b.disabled=false}};
